import React, { useState, useEffect } from 'react';
import { Card, Button, api } from '../App';

export default function ReportsPage() {
  const [saleNos,     setSaleNos]     = useState([]);
  const [selSale,     setSelSale]     = useState('');
  const [activeTab,   setActiveTab]   = useState('party'); // 'party' | 'market'

  // Party report
  const [partyData,   setPartyData]   = useState([]);
  const [expanded,    setExpanded]    = useState(null); // party_code
  const [loadingParty,setLoadingParty]= useState(false);

  // Market report
  const [marketData,  setMarketData]  = useState([]);
  const [mktGrade,    setMktGrade]    = useState('');
  const [loadingMkt,  setLoadingMkt]  = useState(false);

  useEffect(() => {
    api.get('/import/sale-numbers').then(r => { setSaleNos(r.data); if (r.data[0]) setSelSale(String(r.data[0].sale_no)); }).catch(() => {});
  }, []);

  const loadPartyReport = async () => {
    if (!selSale) return;
    setLoadingParty(true);
    try {
      const r = await api.get(`/reports/party-summary?sale_no=${selSale}`);
      setPartyData(r.data);
    } catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingParty(false); }
  };

  const loadMarketReport = async () => {
    if (!selSale) return;
    setLoadingMkt(true);
    try {
      const r = await api.get(`/reports/market?sale_no=${selSale}`);
      setMarketData(r.data);
    } catch (e) { alert(e.response?.data?.error || e.message); }
    finally { setLoadingMkt(false); }
  };

  useEffect(() => {
    if (!selSale) return;
    if (activeTab === 'party')  loadPartyReport();
    if (activeTab === 'market') loadMarketReport();
  }, [selSale, activeTab]);

  const grades = [...new Set(marketData.map(r => r.grade))].sort();
  const filteredMarket = mktGrade ? marketData.filter(r => r.grade === mktGrade) : marketData;

  // Group market data by grade for display
  const mktByGrade = {};
  filteredMarket.forEach(row => {
    if (!mktByGrade[row.grade]) mktByGrade[row.grade] = [];
    mktByGrade[row.grade].push(row);
  });

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>📊 Reports</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Party marking report and market price report from sold list.</p>

      {/* Controls */}
      <Card style={{ marginBottom: 16, padding: 14 }}>
        <div style={{ display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }}>
          <div>
            <label style={{ fontSize: 11, fontWeight: 700, color: '#555', textTransform: 'uppercase', letterSpacing: 0.4, marginBottom: 4, display: 'block' }}>Sale Number</label>
            <select value={selSale} onChange={e => setSelSale(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13, minWidth: 200 }}>
              <option value="">Select sale…</option>
              {saleNos.map(s => <option key={s.sale_no} value={s.sale_no}>Sale {s.sale_no} ({s.lot_count} lots)</option>)}
            </select>
          </div>

          {/* Tab buttons */}
          <div style={{ display: 'flex', gap: 8, marginLeft: 'auto' }}>
            {[
              { key: 'party',  label: '👥 Party Report' },
              { key: 'market', label: '📈 Market Report' }
            ].map(t => (
              <button key={t.key} onClick={() => setActiveTab(t.key)}
                style={{ padding: '8px 18px', borderRadius: 6, cursor: 'pointer', fontWeight: 600, fontSize: 13,
                  background: activeTab === t.key ? '#1a3c5e' : '#f0f4f8',
                  color:      activeTab === t.key ? '#fff' : '#555',
                  border:     activeTab === t.key ? 'none' : '1.5px solid #e2e8f0' }}>
                {t.label}
              </button>
            ))}
          </div>
        </div>
      </Card>

      {/* ── PARTY REPORT ── */}
      {activeTab === 'party' && (
        <Card>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
            <h3 style={{ fontSize: 15 }}>Party Marking Report — Sale #{selSale}</h3>
            <div style={{ fontSize: 12, color: '#888' }}>{partyData.length} parties</div>
          </div>

          {loadingParty
            ? <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading…</div>
            : partyData.length === 0
              ? <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No markings found for Sale #{selSale}</div>
              : (
                <div>
                  {partyData.map(party => {
                    const isExp = expanded === party.party_code;
                    return (
                      <div key={party.party_code} style={{ marginBottom: 8, border: '1.5px solid #e2e8f0', borderRadius: 8, overflow: 'hidden' }}>
                        {/* Party row — clickable */}
                        <div onClick={() => setExpanded(isExp ? null : party.party_code)}
                          style={{ padding: '10px 16px', background: isExp ? '#1a3c5e' : '#f8fafc', cursor: 'pointer',
                            display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <span style={{ background: isExp?'rgba(255,255,255,0.2)':'#dbeafe', color: isExp?'#fff':'#1e40af', padding: '2px 10px', borderRadius: 99, fontSize: 12, fontWeight: 700 }}>
                              {party.party_code}
                            </span>
                            <span style={{ fontWeight: 700, fontSize: 14, color: isExp?'#fff':'#1a3c5e' }}>{party.party_name}</span>
                          </div>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                            <span style={{ fontSize: 13, fontWeight: 700, color: isExp?'#90cdf4':'#1a7a4a' }}>
                              {party.total_lots} lots
                            </span>
                            <span style={{ color: isExp?'#fff':'#888', fontSize: 12 }}>{isExp ? '▲' : '▼ Click to view lots'}</span>
                          </div>
                        </div>

                        {/* Expanded lot list */}
                        {isExp && (
                          <div style={{ overflowX: 'auto' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                              <thead>
                                <tr style={{ background: '#f0f4f8' }}>
                                  {['Garden (Mark)','Origin','Grade','Broker','Invoice','Bags','Net Wt','Price ₹'].map(h => (
                                    <th key={h} style={{ padding: '7px 10px', textAlign: 'left', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>{h}</th>
                                  ))}
                                </tr>
                              </thead>
                              <tbody>
                                {(party.lots || []).map((lot, i) => (
                                  <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i%2===0?'#fff':'#fafbfc' }}>
                                    <td style={{ padding: '6px 10px', fontWeight: 700, color: '#1a3c5e' }}>{lot.garden}</td>
                                    <td style={{ padding: '6px 10px', fontSize: 11, color: '#777' }}>{lot.origin || '—'}</td>
                                    <td style={{ padding: '6px 10px' }}>
                                      <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 8px', borderRadius: 99, fontSize: 11, fontWeight: 700 }}>{lot.grade}</span>
                                    </td>
                                    <td style={{ padding: '6px 10px', color: '#555' }}>{lot.broker || '—'}</td>
                                    <td style={{ padding: '6px 10px', fontFamily: 'monospace', fontSize: 11, color: '#888' }}>{lot.invoice || '—'}</td>
                                    <td style={{ padding: '6px 10px' }}>{lot.bags || '—'}</td>
                                    <td style={{ padding: '6px 10px' }}>{lot.net_wt || '—'}</td>
                                    <td style={{ padding: '6px 10px', fontWeight: 600, color: '#1a7a4a' }}>
                                      {lot.price ? `₹${parseFloat(lot.price).toFixed(0)}` : '—'}
                                    </td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )
          }
        </Card>
      )}

      {/* ── MARKET REPORT ── */}
      {activeTab === 'market' && (
        <Card>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
            <div>
              <h3 style={{ fontSize: 15 }}>Market Price Report — Sale #{selSale}</h3>
              <div style={{ fontSize: 12, color: '#888', marginTop: 2 }}>From Sold List — Grade-wise garden prices (Low → High)</div>
            </div>
            <select value={mktGrade} onChange={e => setMktGrade(e.target.value)}
              style={{ padding: '7px 12px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }}>
              <option value="">All Grades</option>
              {grades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
          </div>

          {loadingMkt
            ? <div style={{ padding: 30, textAlign: 'center', color: '#888' }}>⏳ Loading…</div>
            : marketData.length === 0
              ? <div style={{ padding: 30, textAlign: 'center', color: '#aaa' }}>No sold list data for Sale #{selSale}. Upload Sold List first.</div>
              : (
                <div>
                  {Object.entries(mktByGrade).map(([grade, rows]) => {
                    const gradeMin = Math.min(...rows.map(r => parseFloat(r.price_low)||Infinity));
                    const gradeMax = Math.max(...rows.map(r => parseFloat(r.price_high)||0));
                    return (
                      <div key={grade} style={{ marginBottom: 20 }}>
                        {/* Grade header */}
                        <div style={{ background: '#1a3c5e', color: '#fff', padding: '8px 14px', borderRadius: '8px 8px 0 0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                            <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 10px', borderRadius: 99, fontSize: 13, fontWeight: 700 }}>{grade}</span>
                            <span style={{ fontSize: 12, opacity: 0.8 }}>{rows.length} gardens</span>
                          </div>
                          <div style={{ fontSize: 13, fontWeight: 700 }}>
                            Range: ₹{gradeMin.toFixed(0)} – ₹{gradeMax.toFixed(0)}
                          </div>
                        </div>
                        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12, borderRadius: '0 0 8px 8px', overflow: 'hidden', border: '1px solid #e2e8f0' }}>
                          <thead>
                            <tr style={{ background: '#f0f4f8' }}>
                              {['Garden (Mark)','Origin','Broker','Lots','Bags','Low ₹','High ₹','Avg ₹','Buyers'].map(h => (
                                <th key={h} style={{ padding: '7px 10px', textAlign: h==='Low ₹'||h==='High ₹'||h==='Avg ₹'?'right':'left', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>{h}</th>
                              ))}
                            </tr>
                          </thead>
                          <tbody>
                            {rows.sort((a,b) => parseFloat(a.price_low)-parseFloat(b.price_low)).map((row, i) => {
                              const pct = gradeMax > gradeMin
                                ? ((parseFloat(row.price_high)-gradeMin)/(gradeMax-gradeMin))*100
                                : 50;
                              return (
                                <tr key={i} style={{ borderBottom: '1px solid #f0f4f8', background: i%2===0?'#fff':'#fafbfc' }}>
                                  <td style={{ padding: '7px 10px', fontWeight: 700, color: '#1a3c5e' }}>{row.garden}</td>
                                  <td style={{ padding: '7px 10px', fontSize: 11, color: '#777' }}>{row.origin||'—'}</td>
                                  <td style={{ padding: '7px 10px', color: '#555' }}>{row.broker||'—'}</td>
                                  <td style={{ padding: '7px 10px', textAlign: 'center' }}>{row.lot_count}</td>
                                  <td style={{ padding: '7px 10px', textAlign: 'center' }}>{row.total_bags||'—'}</td>
                                  <td style={{ padding: '7px 10px', textAlign: 'right', color: '#1a7a4a', fontWeight: 600 }}>
                                    ₹{parseFloat(row.price_low).toFixed(0)}
                                  </td>
                                  <td style={{ padding: '7px 10px', textAlign: 'right', color: '#c0392b', fontWeight: 600 }}>
                                    ₹{parseFloat(row.price_high).toFixed(0)}
                                  </td>
                                  <td style={{ padding: '7px 10px', textAlign: 'right', color: '#1a3c5e', fontWeight: 600 }}>
                                    ₹{parseFloat(row.price_avg).toFixed(0)}
                                  </td>
                                  <td style={{ padding: '7px 10px', fontSize: 11, color: '#888' }}>
                                    {(row.buyers||[]).filter(Boolean).slice(0,5).join(', ')||'—'}
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    );
                  })}
                </div>
              )
          }
        </Card>
      )}
    </div>
  );
}
